#!/usr/bin/env node
// After each turn, keeps the coded lines from the assistant's own messages in
// runs/log.jsonl. It reads the final message from the hook input and earlier
// messages of the turn from the transcript, by position since its last run. It
// never reads a user message, tool output, or a file for codes, never blocks,
// and prints nothing. It does nothing from a plugin install, where it would
// run in every session. Generated by Agent Studio. It needs no packages.
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

if (process.env.CLAUDE_PLUGIN_ROOT) process.exit(0);
try {
  const input = JSON.parse(readFileSync(0, "utf8") || "{}");
  const sessionId = String(input.session_id || "");
  if (sessionId) {
    const log = await import("./run-log.mjs");
    const root = log.projectRoot();
    const stateFile = join(root, log.STATE, log.sessionHash(sessionId) + ".json");
    let state = { offset: 0, last: "", pending: false };
    try { state = { ...state, ...JSON.parse(readFileSync(stateFile, "utf8")) }; } catch {}
    // A message is known by the lines it would log, so the same message seen
    // in the hook input and in the transcript is logged once.
    const key = (t) => createHash("sha256").update(JSON.stringify(log.extract(t))).digest("hex");
    const read = typeof input.transcript_path === "string" ? log.assistantTexts(input.transcript_path, Number(state.offset) || 0) : { texts: [], offset: Number(state.offset) || 0 };
    let texts = read.texts;
    // The final message of the last turn may reach the transcript only now;
    // it was already logged from that turn's hook input.
    if (state.pending && texts.length && key(texts[0]) === state.last) texts = texts.slice(1);
    const last = typeof input.last_assistant_message === "string" ? input.last_assistant_message : "";
    const lastKey = key(last);
    const flushed = texts.length > 0 && key(texts[texts.length - 1]) === lastKey;
    const lines = texts.flatMap((t) => log.extract(t));
    if (last && !flushed) lines.push(...log.extract(last));
    log.append(root, sessionId, lines);
    mkdirSync(join(root, log.STATE), { recursive: true });
    writeFileSync(stateFile, JSON.stringify({ offset: read.offset, last: lastKey, pending: Boolean(last) && !flushed }));
  }
} catch {}
process.exit(0);
